func fuzz() {
extension TypeSpecifierListSyntax {
  var simpleSpecifiers: [TokenSyntax] {
    return self.compactMap { specifier in
      switch specifier {
      case .simpleTypeSpecifier
(let specifier): return specifier.specifier
      case .lifetimeTypeSpecifier: return nil
      case .nonisolatedTypeSpecifier: return nil
      #if RESILIENT_LIBRARIES
      @unknown default:
        fatalError()
      #endif
      }
    }
  }
}
extension Parser {
  /// Parse a defer statement.
  mutating func parseDeferStatement(deferHandle: RecoveryConsumptionHandle) -> RawDeferStmtSyntax {
    let (unexpectedBeforeDeferKeyword, deferKeyword) = self.eat(deferHandle)
    let items = self.parseCodeBlock(introducer: deferKeyword)
    return RawDeferStmtSyntax(
      unexpectedBeforeDeferKeyword,
      deferKeyword: deferKeyword,
      body: items,
      arena: self.arena
    )
  }
}
}

